// SPDX-License-Identifier: AGPL-3.0-only
// Generates src/generated.ts from openapi.json (itself generated by the control plane). Covers
// the subset of OpenAPI 3.1 the control plane emits; anything else fails loudly.
import { readFileSync, writeFileSync } from "node:fs";

type Schema = {
  type?: string | string[];
  $ref?: string;
  enum?: string[];
  oneOf?: Schema[];
  items?: Schema;
  properties?: Record<string, Schema>;
  required?: string[];
  description?: string;
};
type Operation = { operationId: string; description?: string; summary?: string; security?: unknown[]; responses: Record<string, { content?: { "application/json"?: { schema: Schema } } }> };
type Doc = { info: { version: string }; paths: Record<string, { get?: Operation }>; components: { schemas: Record<string, Schema> } };

const doc = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as Doc;

const comment = (text: string | undefined, indent = "") =>
  text ? `${indent}/** ${text.trim().replace(/\*\//g, "*\\/").replace(/\n+/g, ` `)} */\n` : "";

function ts(s: Schema, indent: string): string {
  if (s.$ref) return s.$ref.replace("#/components/schemas/", "");
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (s.oneOf) return s.oneOf.map((x) => ts(x, indent)).join(" | ");
  const types = Array.isArray(s.type) ? s.type : s.type ? [s.type] : [];
  const nonNull = types.filter((t) => t !== "null");
  const nullable = types.includes("null") ? " | null" : "";
  if (nonNull.length > 1) throw new Error(`unsupported union ${JSON.stringify(s)}`);
  switch (nonNull[0]) {
    case "string": return `string${nullable}`;
    case "boolean": return `boolean${nullable}`;
    case "integer": case "number": return `number${nullable}`;
    case "array": return `${wrap(ts(s.items ?? {}, indent))}[]${nullable}`;
    case "object": {
      if (!s.properties) return `Record<string, unknown>${nullable}`;
      const req = new Set(s.required ?? []);
      const inner = indent + "  ";
      const fields = Object.entries(s.properties).map(([k, v]) => `${comment(v.description, inner)}${inner}${k}${req.has(k) ? "" : "?"}: ${ts(v, inner)};`);
      return `{\n${fields.join("\n")}\n${indent}}${nullable}`;
    }
    case undefined: return "unknown";
    default: throw new Error(`unsupported type ${JSON.stringify(s)}`);
  }
}
const wrap = (t: string) => (t.includes("|") ? `(${t})` : t);

const out: string[] = [
  "// SPDX-License-Identifier: AGPL-3.0-only",
  "// GENERATED by scripts/generate.ts from openapi.json. Do not edit; run `npm run api:generate`.",
  "",
  `export const API_VERSION = ${JSON.stringify(doc.info.version)};`,
  "",
];
for (const [name, s] of Object.entries(doc.components.schemas)) {
  out.push(`${comment(s.description)}export type ${name} = ${ts(s, "")};`, "");
}

const ops = Object.entries(doc.paths).flatMap(([path, item]) => (item.get ? [{ path, op: item.get }] : []));
out.push("/** GET operations by operationId: path, success body and whether a token is needed. */");
out.push("export const operations = {");
for (const { path, op } of ops) out.push(`  ${op.operationId}: { path: ${JSON.stringify(path)}, public: ${JSON.stringify(op.security?.length === 1 && JSON.stringify(op.security[0]) === "{}")} },`);
out.push("} as const;", "");
out.push("export type Responses = {");
for (const { op } of ops) {
  const ok = op.responses["200"]?.content?.["application/json"]?.schema;
  if (!ok) throw new Error(`${op.operationId}: no 200 JSON response`);
  out.push(`${comment(op.description ?? op.summary, "  ")}  ${op.operationId}: ${ts(ok, "  ")};`);
}
out.push("};", "");

writeFileSync(new URL("../src/generated.ts", import.meta.url), out.join("\n"));
console.log(`api client generated: ${Object.keys(doc.components.schemas).length} types, ${ops.length} operations`);
